# previous video's nextHandoff), start, stop, entry [(source, idea)], owns (sub-points owned, by id suffix), later [later homes],
# models (recurring models: 'intro:<name>' or 'reuse:<name>'), visual (anchor visuals and plate needs), overlap (cross-year note).
S5 = "Stage 5 PDHPE (assumed, not re-taught)"
Y11 = "Year 11 HMS (recalled in one sentence; do not assume our Year 11 video was watched)"

V = []
def v(**k): V.append(k)

